from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 1

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
    ) -> int:
        if start < now:
            raise ValueError("Appointment cannot start in the past")
        if not self.is_free(doctor, start, end):
            raise ValueError("Doctor is not available")

        appointment_id = self._next_id
        self._next_id += 1
        self._appointments[appointment_id] = (patient, doctor, start, end)
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        _, _, start, _ = self._appointments[appointment_id]
        if start - now >= timedelta(hours=24):
            del self._appointments[appointment_id]

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        if end <= start:
            raise ValueError("Appointment must end after it starts")

        return not any(
            booked_doctor == doctor and start < booked_end and booked_start < end
            for _, booked_doctor, booked_start, booked_end
            in self._appointments.values()
        )
